-- ASH blog ve marka yonetimi. Supabase SQL Editor'de bir kez calistirin.
-- Once Authentication > Users bolumunde yonetici kullaniciyi olusturun.
begin;

do $$ begin
  if not exists (select 1 from auth.users where lower(email) = 'selahattin.guldes@gmail.com') then
    raise exception 'Once Authentication > Users alaninda selahattin.guldes@gmail.com kullanicisini olusturun, sonra bu dosyayi tekrar calistirin.';
  end if;
end $$;

create table if not exists public.ash_admins (
  user_id uuid primary key references auth.users(id) on delete cascade,
  created_at timestamptz not null default now()
);
alter table public.ash_admins enable row level security;
revoke all on public.ash_admins from anon, authenticated;
grant select on public.ash_admins to authenticated;
drop policy if exists "ash_admin_reads_own_membership" on public.ash_admins;
create policy "ash_admin_reads_own_membership" on public.ash_admins for select to authenticated using (user_id = (select auth.uid()));

insert into public.ash_admins(user_id)
select id from auth.users where lower(email) = 'selahattin.guldes@gmail.com'
on conflict do nothing;

create table if not exists public.ash_blog_posts (
  id uuid primary key default gen_random_uuid(),
  locale text not null check (locale in ('tr', 'en')),
  translation_key text not null check (translation_key ~ '^[a-z0-9-]{1,160}$'),
  slug text not null check (length(slug) <= 140 and slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  status text not null default 'draft' check (status in ('draft', 'published')),
  content jsonb not null check (jsonb_typeof(content) = 'object' and content->>'slug' = slug),
  version integer not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (locale, slug),
  unique (locale, translation_key)
);
alter table public.ash_blog_posts enable row level security;
revoke all on public.ash_blog_posts from anon, authenticated;
grant select on public.ash_blog_posts to anon;
grant select, insert, update, delete on public.ash_blog_posts to authenticated;
create index if not exists ash_blog_published_date_idx on public.ash_blog_posts ((content->>'date') desc) where status = 'published';

drop policy if exists "ash_public_reads_published" on public.ash_blog_posts;
create policy "ash_public_reads_published" on public.ash_blog_posts for select to anon using (status = 'published' and content->>'date' <= current_date::text);
drop policy if exists "ash_member_reads_posts" on public.ash_blog_posts;
create policy "ash_member_reads_posts" on public.ash_blog_posts for select to authenticated using (
  (status = 'published' and content->>'date' <= current_date::text)
  or exists (select 1 from public.ash_admins where user_id = (select auth.uid()))
);
drop policy if exists "ash_admin_inserts_posts" on public.ash_blog_posts;
create policy "ash_admin_inserts_posts" on public.ash_blog_posts for insert to authenticated with check (exists (select 1 from public.ash_admins where user_id = (select auth.uid())));
drop policy if exists "ash_admin_updates_posts" on public.ash_blog_posts;
create policy "ash_admin_updates_posts" on public.ash_blog_posts for update to authenticated
  using (exists (select 1 from public.ash_admins where user_id = (select auth.uid())))
  with check (exists (select 1 from public.ash_admins where user_id = (select auth.uid())));
drop policy if exists "ash_admin_deletes_posts" on public.ash_blog_posts;
create policy "ash_admin_deletes_posts" on public.ash_blog_posts for delete to authenticated using (exists (select 1 from public.ash_admins where user_id = (select auth.uid())));

create or replace function public.ash_touch_blog_post() returns trigger
language plpgsql security invoker set search_path = '' as $$
begin
  new.updated_at := now();
  new.version := old.version + 1;
  return new;
end $$;
revoke all on function public.ash_touch_blog_post() from public, anon, authenticated;
drop trigger if exists ash_blog_updated on public.ash_blog_posts;
create trigger ash_blog_updated before update on public.ash_blog_posts for each row execute function public.ash_touch_blog_post();

create table if not exists public.ash_site_settings (
  id text primary key check (id = 'site'),
  settings jsonb not null check (jsonb_typeof(settings) = 'object'),
  updated_at timestamptz not null default now()
);
alter table public.ash_site_settings enable row level security;
revoke all on public.ash_site_settings from anon, authenticated;
grant select on public.ash_site_settings to anon, authenticated;
grant update on public.ash_site_settings to authenticated;
drop policy if exists "ash_public_reads_brand" on public.ash_site_settings;
create policy "ash_public_reads_brand" on public.ash_site_settings for select to anon, authenticated using (true);
drop policy if exists "ash_admin_updates_brand" on public.ash_site_settings;
create policy "ash_admin_updates_brand" on public.ash_site_settings for update to authenticated
  using (exists (select 1 from public.ash_admins where user_id = (select auth.uid())))
  with check (exists (select 1 from public.ash_admins where user_id = (select auth.uid())));
insert into public.ash_site_settings(id, settings) values ('site', '{"logoLight":"/brand/ash-dark.svg","logoDark":"/brand/ash-light.svg","favicon":"/theme/favicon.svg"}') on conflict do nothing;

insert into storage.buckets(id, name, public, file_size_limit, allowed_mime_types)
values ('ash-media', 'ash-media', true, 3145728, array['image/webp', 'image/png'])
on conflict (id) do nothing;
drop policy if exists "ash_admin_uploads_media" on storage.objects;
create policy "ash_admin_uploads_media" on storage.objects for insert to authenticated with check (
  bucket_id = 'ash-media' and (storage.foldername(name))[1] = (select auth.uid())::text
  and exists (select 1 from public.ash_admins where user_id = (select auth.uid()))
);
drop policy if exists "ash_admin_reads_media" on storage.objects;
create policy "ash_admin_reads_media" on storage.objects for select to authenticated using (
  bucket_id = 'ash-media' and exists (select 1 from public.ash_admins where user_id = (select auth.uid()))
);

-- Mevcut yayinlar asagida eklenir; tekrar calistirmak duzenlenmis yazilari ezmez.

insert into public.ash_blog_posts(locale,translation_key,slug,status,content) values ('tr','crm-yapay-zeka-satis-otomasyonu','crm-yapay-zeka-satis-otomasyonu','published','{"slug": "crm-yapay-zeka-satis-otomasyonu", "title": "CRM Yapay Zekâ: Satış Verisi Neden Güncel Kalmaz?", "metaDescription": "Satış ekipleri CRM''i neden güncel tutamaz, eksik veri tahmini nasıl bozar? CRM yapay zekâ ve satış otomasyonu bu zinciri tam olarak nerede kırar?", "category": "CRM ve Satış Otomasyonu", "summary": "Bir görüşmeden kayda, kayıttan tahmine uzanan akışı izleyerek CRM''in neden güncel kalmadığına bakıyoruz: kayıt yükü, eksik veriyle üretilen tahmin, fırsat skorlaması, dağılmış müşteri verisi ve kişisel veri tarafında dikkat edilmesi gerekenler.", "readingMinutes": 6, "date": "2026-09-17", "author": {"name": "ASH Ekibi", "role": "CRM ve Satış Çözümleri"}, "intro": ["Bir satış temsilcisinin günü nadiren masa başında geçer. Sabah bir görüşme, öğleden sonra iki ziyaret, aralarda e-posta ve mesajlaşma uygulamasından gelen sorular. Gün bittiğinde elde kalan şey, hiçbiri henüz sisteme girilmemiş birkaç ayrı bağlamdır.", "CRM yapay zekâ başlığı çoğunlukla yanlış uçtan açılır: skorlama, tahmin, otomatik rapor. Oysa bunların hepsi girdi olarak aynı eksik kaydı kullanır. Aşağıda bir görüşmeden kayda, kayıttan tahmine uzanan akışı izliyor; her durakta neyin koptuğuna ve yapay zekânın bu zinciri tam olarak nerede kırdığına bakıyoruz."], "sections": [{"heading": "Satış ekipleri CRM''i neden güncellemez?", "paragraphs": ["Bir ziyareti kaydetmek için uygulamayı açmak, doğru hesabı bulmak, aktivite formuna gitmek ve sıra sıra zorunlu alanı doldurmak gerekir; üstelik çoğu zaman araç park yerinde, telefon ekranından. Temsilci bu işi ertelediğinde disiplinsiz davranmış olmaz, günde kaç durak için aynı şeyi tekrarlayacağını hesaplamış olur.", "İkinci neden daha yapısaldır: kaydı giren kişi ile faydasını gören kişi aynı değildir. Temsilci doldurur, tablo yöneticinin toplantısında açılır. Sisteme giren bilgi temsilciye bir sonraki adımı, bekleyen takibi veya riski geri vermiyorsa kayıt bir kazanç değil, ek mesai olarak hissedilir.", "Üçüncüsü çoğu yöneticinin sezgisine terstir. Her yeni raporlama ihtiyacında \"görünürlük olsun\" diye bir zorunlu alan eklenir; form uzadıkça doldurma özeni azalır ve isteğe bağlı alanlar çoğunlukla boş kalır. Zorunluluğu artırmak veri kalitesini yükseltmez, çoğu zaman alanların yalnızca uyarıyı kapatmak için doldurulmasına yol açar."]}, {"heading": "Eksik veriden üretilen tahmin neden güvenilmez?", "paragraphs": ["Bir CRM, olan bitenin değil, yazmaya vakit bulunanın kaydıdır. Rapor bu kaydın üzerinden çalıştığında gördüğünüz şey bugünkü fırsat değil, en son ne zaman yazmaya vakit bulunduysa o günkü halidir. Tahmin de aynı gecikmeyi miras alır.", "Boşluklar sayıya dönüşürken görünmez olur. Aşama çıkış kriteri tanımlı değilse haftalardır hareket görmemiş bir \"teklif gönderildi\" kaydı, canlı bir fırsatla aynı ağırlıkta toplanır ve hattı olduğundan güçlü gösterir. Kapanış tarihinin sessizce ileri alınması en okunaklı kayma sinyalidir; gerekçesi not edilmediğinde raporda yalnızca bir tarih değişikliği olarak görünür.", "Buna teşvik kaynaklı çarpıtmalar eklenir: kimi temsilci sayıyı korumak için hattını zayıf gösterir, kimi de duymak istediğini duyup taahhüt eder. Bunlar veri sorunu değil, teşvik sorunudur. Asıl mesele şu ki kayıt bugün eksik bırakıldığında kayıp orada kalmaz; aynı boşluk birkaç ay sonra modelin öğrendiği örüntünün içine yerleşir ve sistem bir süre sonra rapor üretmeyi bırakıp kendinden emin bir kanaat üretmeye başlar."]}, {"heading": "Görüşme notu, e-posta ve toplantı kayda nasıl dönüşür?", "paragraphs": ["Satış otomasyonundan beklenen şey genellikle rapordur; oysa asıl işi kaydın kendisini üretmektir. Takvim daveti, e-posta yazışması ve toplantı notu zaten mevcut içeriktir. Yapay zekânın buradaki katkısı bu içeriği yapılandırılmış alana çevirmek, yani temsilciden aynı bilgiyi ikinci kez yazmasını istememektir.", "CRM-X gibi çözümlerde de görüşme sonrası serbest metinle yazılan nottan karar, itiraz ve sonraki tarih ayıklanır; alanlar kullanıcının onayıyla dolar. Ölçüt de buradan çıkar: bir araç kaydı zenginleştiriyor ama temsilcinin yazma süresini kısaltmıyorsa, çözdüğü sorun raporlamadır, veri girişi değil.", "Bu katman sanıldığı kadar kesin değildir. Otomatik aktivite eşleştirmesi ağırlıklı olarak e-posta adresine bakar; ortak kutular, kişisel adresinden yazan muhatap veya henüz sistemde olmayan aday sistematik biçimde yanlış yere düşer. Ses tarafında gürültü, aksan ve araya giren konuşmalar hata üretir; asıl sinsi hata ise atlamadır, çünkü \"önce hukuk onayı gerekiyor\" gibi tek cümlelik bir şart özetten düştüğünde metin kusursuz göründüğü için kimse geri dönüp bakmaz.", "Doğru kurgu özeti kanıt değil taslak sayar. Her çıkarımın görüşme metnindeki yerine bağlanabilmesi, tek gerçek doğrulama yöntemidir. Yazma yetkisi de kademelendirilmelidir: düşük riskli alanlar otomatik dolabilir, fiyat ve taahhüt gibi alanlar insan onayından geçmelidir. Eşleşmeyen aktivitelerin oranını düzenli ölçmek de bu katmanın bakımının parçasıdır."]}, {"heading": "Bugün hangi fırsata bakmalı?", "paragraphs": ["Sahadaki soru \"hattın genel durumu nedir\" değil, \"bugün hangi üç fırsata bakayım\" sorusudur. Fırsat skorlaması tam olarak bunun karşılığıdır: geçmişte kazanılan ve kaybedilen kayıtlardan öğrenilen bir sıralama. Çalışması için yeterli sayıda kapanmış kayıt ve en az onun kadar önemlisi, kayıp nedeninin gerçekten yazılmış olması gerekir; kapanan iş sayısı azsa skor bilgi değil gürültü üretir.", "Skorun iki bilinen zayıf noktası vardır. Yüksek skor verilen fırsata daha çok dokunulur, o fırsat kapanır ve model haklı çıkmış sayılır; aslında alıcının niyetini değil temsilcinin davranışını tahmin etmiştir. İkincisi, ürün, fiyatlandırma veya hedef segment değiştiğinde öğrenilen ilişki bozulur. Bu nedenle skor bir kapı değil, öncelik sırası olarak kullanılmalı ve yeniden değerlendirme takvime bağlanmalıdır.", "Öneri tarafında ölçüt daha da basittir: gerekçesi görünmeyen öneri benimsenmez. \"Müşteriyi arayın\" bir öneri değildir; \"teklif dokuz gündür yanıtsız ve karar verici hiçbir görüşmeye katılmadı\" ifadesi ise temsilcinin kendi bildiğiyle karşılaştırabileceği bir gerekçedir. Kırk fırsata aynı gün aynı şeyi söylemek de uygulanabilir olmadığından, kapasite önerinin bir parçası olmalıdır."]}, {"heading": "Müşteri verisi dağıldığında tek kayıt ne sağlar?", "paragraphs": ["Aynı müşterinin bilgisi çoğu kurumda tek bir yerde durmaz: e-posta kutusunda, kişisel bir tabloda, mesajlaşma uygulamasında ve ERP''de aynı anda yaşar. Resmî sistem sürtünme ürettiğinde temsilci kendi sistemini kurar ve tablo, özellik zenginliğiyle değil iki saniyede açılmasıyla kazanır. Tek kayıt fikri bu yüzden önemlidir: müşteri, fırsat ve aktivite aynı yerde durmadığı sürece temsilci kendi kopyasını tutmaya devam eder ve resmî sistem her gün biraz daha geriden gelir.", "Tek kayıt bir derleme işi değil, kimlik işidir. Sağlıklı yöntem katmanlıdır: önce vergi numarası, alan adı veya normalize edilmiş telefon gibi kesin anahtarlarla eşleştirme, kalanlar için benzerlik skoru. Türkçede kendine özgü tuzaklar da vardır; büyük-küçük harf dönüşümünde i ve I, sadeleştirmede ğ, ş, ü gibi harfler ve A.Ş. yazımındaki farklar eşleştirmeyi zorlaştırır.", "Birleştirme kararının riski simetrik değildir. Kaçan bir mükerrer kayıt sonradan düzeltilebilir; yanlış birleştirme ise iki farklı müşterinin geçmişini, sözleşmesini ve iletişim iznini karıştırır ve çoğu sistemde geri alınamaz. O yüzden otomatik birleştirme bandı dar tutulmalı, şüpheli çiftler insana sorulmalı ve her birleştirme geriye dönük izlenebilir kalmalıdır."]}, {"heading": "KVKK ve denetlenebilirlik açısından nelere dikkat etmeli?", "paragraphs": ["Kapsamın en hızlı genişlediği yer otomatik aktivite yakalamadır. Filtresiz bir posta kutusu senkronu özel yazışmaları ve üçüncü kişilerin verisini de içeri taşır; aynı zamanda bir çalışan izleme uygulamasına dönüşür. Veri minimizasyonunun somut karşılığı burada kademeli modlardır: izinli alan adı listesi, yalnızca giden yazışmalar ya da içerik yerine yalnızca üstveri. Pek çok satış metriği için kimin kiminle ne zaman görüştüğü bilgisi zaten yeterlidir.", "Ses kaydı ve özetleme en dikkat gerektiren başlıktır. Kayıt başlamadan aydınlatma yapılmalı, karşı taraf kabul etmediğinde kayıtsız ilerleyebilen bir akış bulunmalıdır. Özet de kayıttan türetilmiş yeni bir kişisel veridir; düzeltme veya silme talebi geldiğinde ses kaydı, metin, özet, bunlardan doldurulmuş alanlar ve arama dizini birlikte ele alınmalıdır. Bu akışı sonradan eklemek ise hem teknik hem hukuki olarak pahalıdır; geriye dönük kayıtların çoğunda aydınlatmanın yapıldığını kanıtlamak artık mümkün olmaz.", "Denetlenebilirlik ise tek bir soruya indirgenebilir: bu alan nereden geldi? Hangi önerinin hangi kayda dayandığı, hangi alanı kimin ne zaman değiştirdiği ve skorun neye göre üretildiği görünür olmalıdır. Kişi hakkında sonuç doğuran kararlarda insan denetimi biçimsel kalmamalı; model ve metne çevirme sağlayıcılarının her biri ayrı bir yurt dışı aktarımı doğurabileceği için alt işleyen zinciri baştan netleştirilmelidir. Rol bazlı yetki ve zaman damgalı değişiklik geçmişi, yapay zekâ katmanının yanında değil altında durmalıdır."]}], "takeaways": ["CRM güncel kalmaz çünkü kaydı giren kişi ile faydasını gören kişi aynı değildir; benimseme talimatla değil, sistemin geri verdiği değerle oluşur.", "Zorunlu alan eklemek veri kalitesini yükseltmez; form uzadıkça kayıt sinyal üretmek için değil, uyarıyı kapatmak için doldurulur.", "Rapor ve tahmin, olan biteni değil yazmaya vakit bulunanı gösterir; aşama kirliliği ve ötelenen kapanış tarihi bu boşluğu sayıya çevirir.", "Yapay zekânın satıştaki asıl katkısı rapor üretmek değil, görüşme notunu, e-postayı ve toplantıyı veri girişi olmadan kayda dönüştürmektir; buna rağmen özet kanıt değil taslaktır.", "Fırsat skoru bir kapı değil öncelik sırasıdır; kayıp nedeni yazılmazsa döngü kapanmaz ve gerekçesi görünmeyen öneri sahada benimsenmez.", "Tek kayıt bir kimlik işidir ve yanlış birleştirmenin maliyeti kaçan mükerrer kayıttan yüksektir; otomatik yakalamada minimizasyon, yetki ve iz kaydı baştan tasarlanmalıdır."], "faq": [{"q": "Yapay zekâ destekli CRM ile klasik CRM arasındaki fark nedir?", "a": "Klasik CRM bir kayıt sistemidir: olan biteni siz girersiniz, o saklar. Yapay zekâ destekli yaklaşımda fark iki yerde ortaya çıkar. Birincisi kaydın oluşma biçimidir; görüşme notu, e-posta ve toplantı yapılandırılmış alana çevrildiği için giriş yükü temsilcinin üzerinden kalkar. İkincisi çıktının yönüdür: sistem yalnızca tablo göstermez, bekleyen takibi ve soğuyan fırsatı gerekçesiyle işaretler. Fark özellik listesinde değil, kayıt işinin kimde kaldığındadır."}, {"q": "Satış ekibim CRM''i kullanmıyorsa nasıl benimsetirim?", "a": "Zorlama tek başına benimseme üretmez; form uzadıkça kayıt göstermelik hale gelir. Kalıcı çözüm, sistemin veriyi girenlere de bir şey döndürmesidir: günlük öncelik listesi, hatırlatılan takip, hazır gelen görüşme geçmişi. Zorunlu alan sayısını gerçekten karar verilen birkaç alana indirmek ve kaydın büyük kısmını otomatik üretmek, çoğu ekipte takip baskısını artırmaktan daha hızlı sonuç verir."}, {"q": "Yapay zekânın ürettiği satış tahmini ne kadar güvenilir?", "a": "Tahminin doğruluğu modelden çok altındaki verinin tazeliğine ve bütünlüğüne bağlıdır. Aktiviteler günler sonra giriliyorsa, aşamalar arasında net geçiş kriteri yoksa veya kayıp nedeni yazılmıyorsa sonuç bugünü değil geçmişi anlatır. Ürün, fiyatlandırma ve hedef müşteri profili değiştiğinde geçmişten öğrenilen ilişki de bozulur; bu nedenle tahmin periyodik olarak yeniden değerlendirilmelidir."}, {"q": "Excel''de müşteri takibi ne zaman yetmemeye başlar?", "a": "Tek kişinin yürüttüğü, az sayıda fırsatın olduğu bir süreçte tablo dosyası işini görür. Sorun ekip büyüdüğünde başlar: aynı firma birden fazla dosyada açılır, takip kişinin hafızasına bağlı kalır ve bir kişi ayrıldığında geçmiş de onunla gider. Aynı müşteriye ait güncel bilginin kimde olduğunu sormak gerekiyorsa geçiş zamanı gelmiş demektir."}, {"q": "Görüşme kayıtlarının yapay zekâyla işlenmesi KVKK açısından sorun yaratır mı?", "a": "Doğru kurgulandığında mümkündür, ancak birkaç başlık baştan çözülmelidir. Kayıt başlamadan aydınlatma yapılmalı ve kaydı istemeyen muhatapla kayıtsız devam edebilen bir akış bulunmalıdır. Kayıttan üretilen metin ve özet de kişisel veridir; silme ve düzeltme talepleri ses kaydını, metni, özeti ve arama dizinini birlikte kapsamalıdır. Model ve metne çevirme hizmetleri yurt dışına aktarım doğurabileceğinden alt işleyen zinciri ile saklama süreleri sözleşmede netleşmelidir."}], "cover": "/images/ash-blog-crm.svg", "seoTitle": "CRM Yapay Zekâ ve Satış Otomasyonu", "coverAlt": ""}'::jsonb) on conflict (locale,slug) do nothing;

insert into public.ash_blog_posts(locale,translation_key,slug,status,content) values ('en','crm-yapay-zeka-satis-otomasyonu','crm-ai-sales-automation','published','{"slug": "crm-ai-sales-automation", "title": "CRM AI: Why Doesn''t Sales Data Stay Up to Date?", "metaDescription": "Why can''t sales teams keep the CRM up to date, and how does missing data break the forecast? Where exactly do CRM AI and sales automation break that chain?", "category": "CRM and Sales Automation", "summary": "Following the flow from a conversation to a record and from a record to a forecast, we look at why the CRM doesn''t stay current: the data entry burden, forecasts built on missing data, opportunity scoring, scattered customer data and what to watch out for with personal data.", "readingMinutes": 6, "date": "2026-09-17", "author": {"name": "ASH Team", "role": "CRM and Sales Solutions"}, "intro": ["A sales rep''s day is rarely spent at a desk. A call in the morning, two visits in the afternoon, and questions arriving by email and messaging apps in between. By the end of the day, what''s left is several separate pieces of context, none of which have been entered into the system yet.", "The CRM AI conversation usually starts at the wrong end: scoring, forecasting, automatic reports. Yet all of these use the same incomplete record as their input. Below we follow the flow from a conversation to a record and from a record to a forecast, and at each stop we look at what breaks and where exactly AI breaks the chain."], "sections": [{"heading": "Why don''t sales teams update the CRM?", "paragraphs": ["Logging a visit means opening the app, finding the right account, going to the activity form and filling in required fields one after another, often from a phone screen in a parking lot. When a rep puts this off, they aren''t being undisciplined; they''ve worked out how many stops a day they''d have to repeat it for.", "The second reason is more structural: the person entering the record isn''t the person who benefits from it. The rep fills it in, and the table gets opened in the manager''s meeting. If the information going into the system doesn''t give the rep anything back, such as the next step, a pending follow-up or a risk, the record feels like extra work rather than a gain.", "The third runs against most managers'' intuition. With every new reporting need, a required field is added \"for visibility\"; as the form grows longer, the care taken in filling it drops and optional fields are mostly left empty. Adding requirements doesn''t raise data quality; it often leads to fields being filled in just to dismiss the warning."]}, {"heading": "Why can''t you trust a forecast built on missing data?", "paragraphs": ["A CRM is a record not of what happened, but of what someone found time to write down. When the report runs on that record, what you see isn''t today''s opportunity, but its state on the last day someone found time to write. The forecast inherits the same delay.", "Gaps become invisible as they turn into numbers. If stage exit criteria aren''t defined, a \"proposal sent\" record that hasn''t moved in weeks is added up with the same weight as a live opportunity and makes the pipeline look stronger than it is. A close date that is quietly pushed forward is the clearest sign of slippage; when the reason isn''t noted, it shows up in the report only as a date change.", "Incentive-driven distortions add to this: some reps understate their pipeline to protect their number, others hear what they want to hear and commit. These aren''t data problems but incentive problems. The real issue is that when a record is left incomplete today, the loss doesn''t stay there; a few months later the same gap settles into the pattern the model learns, and after a while the system stops producing reports and starts producing confident opinions."]}, {"heading": "How do meeting notes, emails and meetings become records?", "paragraphs": ["What people usually expect from sales automation is reporting; but its real job is producing the record itself. The calendar invite, the email thread and the meeting notes are content that already exists. AI''s contribution here is turning that content into structured fields, in other words not asking the rep to write the same information a second time.", "In solutions like CRM-X, decisions, objections and the next date are extracted from the free-text note written after a meeting, and fields are filled in with the user''s approval. This also gives you the yardstick: if a tool enriches the record but doesn''t shorten the time the rep spends writing, the problem it solves is reporting, not data entry.", "This layer isn''t as precise as people assume. Automatic activity matching relies mainly on email addresses; shared inboxes, contacts writing from personal addresses or prospects not yet in the system systematically end up in the wrong place. On the audio side, noise, accents and overlapping speech produce errors; the most insidious error, though, is omission, because when a one-sentence condition like \"legal approval is needed first\" drops out of the summary, the text looks flawless and nobody goes back to check.", "The right setup treats the summary as a draft, not as evidence. Being able to link every extracted point back to its place in the conversation transcript is the only real verification method. Write permissions should also be tiered: low-risk fields can be filled in automatically, while fields such as price and commitments should go through human approval. Regularly measuring the share of unmatched activities is also part of maintaining this layer."]}, {"heading": "Which opportunity should you look at today?", "paragraphs": ["The question in the field isn''t \"what''s the overall state of the pipeline?\" but \"which three opportunities should I look at today?\" Opportunity scoring answers exactly that: a ranking learned from records that were won and lost in the past. For it to work, you need enough closed records and, just as importantly, the loss reason actually has to be written down; if the number of closed deals is small, the score produces noise, not information.", "Scoring has two known weak spots. The opportunity with a high score gets more attention, that opportunity closes, and the model is considered right; in fact it predicted the rep''s behavior, not the buyer''s intent. Second, when the product, pricing or target segment changes, the learned relationship breaks down. That''s why the score should be used as a priority order, not a gate, and its re-evaluation should be put on the calendar.", "For recommendations, the yardstick is even simpler: a recommendation without visible reasoning won''t be adopted. \"Call the customer\" isn''t a recommendation; \"the proposal has had no reply for nine days and the decision-maker hasn''t joined any meeting\" is reasoning the rep can compare with what they know. Since telling forty opportunities the same thing on the same day isn''t actionable either, capacity has to be part of the recommendation."]}, {"heading": "What does a single record give you when customer data is scattered?", "paragraphs": ["In most organizations, information about the same customer doesn''t sit in one place: it lives in an inbox, a personal spreadsheet, a messaging app and the ERP all at once. When the official system creates friction, reps build their own, and the spreadsheet wins not on features but because it opens in two seconds. That''s why the idea of a single record matters: as long as customer, opportunity and activity aren''t in the same place, reps keep their own copies and the official system falls a little further behind every day.", "A single record is a matter of identity, not compilation. The healthy method is layered: first match on definitive keys such as tax number, domain name or normalized phone number, then use a similarity score for the rest. Turkish data has its own pitfalls too: the dotted and dotless i in case conversion, letters such as ğ, ş and ü when normalizing, and variant spellings of the company suffix \"A.Ş.\" all make matching harder.", "The risk of a merge decision isn''t symmetrical. A missed duplicate can be fixed later; a wrong merge, however, mixes up two different customers'' histories, contracts and communication consent, and in most systems it can''t be undone. So the automatic merge band should be kept narrow, suspicious pairs should be put to a human, and every merge should remain traceable."]}, {"heading": "What should you watch for in terms of KVKK and auditability?", "paragraphs": ["Automatic activity capture is where the scope grows fastest. An unfiltered mailbox sync also brings in private correspondence and third parties'' data, and at the same time turns into an employee monitoring application. The concrete form of data minimization here is tiered modes: an allowed domain list, outgoing correspondence only, or metadata only instead of content. For many sales metrics, knowing who spoke to whom and when is already enough.", "Call recording and summarization is the topic that needs the most care. Notice must be given before recording starts, and there must be a flow that can proceed without recording if the other party doesn''t agree. The summary is also new personal data derived from the recording; when a correction or deletion request comes in, the audio, the transcript, the summary, the fields filled from them and the search index must all be handled together. Adding this flow later is expensive both technically and legally; for most past recordings it''s no longer possible to prove that notice was given.", "Auditability can be reduced to a single question: where did this field come from? It should be visible which recommendation was based on which record, who changed which field and when, and what the score was based on. In decisions with consequences for a person, human oversight shouldn''t be a formality; and because each model and transcription provider may create a separate cross-border transfer, the chain of sub-processors should be clarified from the start. Role-based permissions and a timestamped change history should sit underneath the AI layer, not beside it."]}], "takeaways": ["The CRM doesn''t stay current because the person entering the record isn''t the person who benefits from it; adoption comes from the value the system gives back, not from instructions.", "Adding required fields doesn''t raise data quality; as the form grows, records get filled in to dismiss the warning, not to produce a signal.", "Reports and forecasts show what someone found time to write, not what happened; stage clutter and pushed close dates turn that gap into numbers.", "AI''s real contribution in sales isn''t producing reports but turning meeting notes, emails and meetings into records without data entry; even so, a summary is a draft, not evidence.", "An opportunity score is a priority order, not a gate; if loss reasons aren''t written down the loop doesn''t close, and recommendations without visible reasoning aren''t adopted in the field.", "A single record is a matter of identity, and a wrong merge costs more than a missed duplicate; in automatic capture, minimization, permissions and audit logging must be designed in from the start."], "faq": [{"q": "What is the difference between an AI-powered CRM and a classic CRM?", "a": "A classic CRM is a system of record: you enter what happened, it stores it. In an AI-powered approach the difference shows up in two places. The first is how the record is created; because meeting notes, emails and meetings are turned into structured fields, the entry burden is lifted from the rep. The second is the direction of the output: the system doesn''t just show a table, it flags pending follow-ups and cooling opportunities with its reasoning. The difference isn''t in the feature list, but in who is left doing the record-keeping."}, {"q": "How do I get my sales team to adopt the CRM if they don''t use it?", "a": "Pressure alone doesn''t create adoption; as the form grows longer, records become a formality. The lasting solution is for the system to give something back to the people entering data: a daily priority list, follow-up reminders, meeting history that''s ready when needed. Cutting required fields down to the few that really drive decisions, and generating most of the record automatically, gets results faster in most teams than increasing follow-up pressure."}, {"q": "How reliable is an AI-generated sales forecast?", "a": "The accuracy of the forecast depends less on the model than on how fresh and complete the underlying data is. If activities are entered days later, if there are no clear criteria for moving between stages or if loss reasons aren''t written down, the result describes the past, not today. When the product, pricing or target customer profile changes, the relationship learned from the past also breaks down; that''s why the forecast should be re-evaluated periodically."}, {"q": "When does tracking customers in Excel stop being enough?", "a": "For a process run by one person with a small number of opportunities, a spreadsheet does the job. The problem starts when the team grows: the same company is opened in more than one file, follow-up depends on someone''s memory, and when a person leaves, the history leaves with them. If you have to ask who has the latest information about a customer, it''s time to switch."}, {"q": "Does processing call recordings with AI create a KVKK issue?", "a": "It''s possible when set up correctly, but a few points must be resolved from the start. Notice must be given before recording begins, and there must be a flow that can continue without recording for a contact who doesn''t want it. The transcript and summary produced from the recording are also personal data; deletion and correction requests must cover the audio, the transcript, the summary and the search index together. Because model and transcription services may involve cross-border transfers, the sub-processor chain and retention periods should be clarified in the contract."}], "cover": "/images/ash-blog-crm.en.svg", "seoTitle": "CRM AI and Sales Automation", "coverAlt": ""}'::jsonb) on conflict (locale,slug) do nothing;

insert into public.ash_blog_posts(locale,translation_key,slug,status,content) values ('tr','golge-ai-kurumsal-yapay-zeka','golge-ai-kurumsal-yapay-zeka','published','{"slug": "golge-ai-kurumsal-yapay-zeka", "title": "Gölge AI: Kurumsal Yapay Zekânın Görünmeyen Riski", "metaDescription": "Çalışanlar kişisel hesaplardan yapay zekâ kullanıyorsa gölge AI çoktan başlamıştır. Riskleri, nedenleri ve kurumsal yapay zekâya geçiş yolunu anlatıyoruz.", "category": "Kurumsal Yapay Zekâ", "summary": "Çalışanların kişisel hesaplardan yapay zekâ araçları kullanması — yani gölge AI — yasakla değil, görünür ve yönetilebilir bir kurumsal yapay zekâ katmanıyla çözülür. Nedenlerini, dört temel riskini ve kurumun atabileceği ilk adımları ele alıyoruz.", "readingMinutes": 5, "date": "2026-09-15", "author": {"name": "ASH Ekibi", "role": "Kurumsal Yapay Zekâ Çözümleri"}, "intro": ["Bir çalışanınız akşam saatlerinde bir sözleşme metnini özetletmek için kişisel hesabıyla girdiği bir yapay zekâ aracına yapıştırıyor. İşini hızlıca bitiriyor, kimseye sormuyor, kimse de haberdar olmuyor. Teknik olarak politika ihlali sayılabilecek bu davranış, çoğu kurumda gün içinde defalarca tekrarlanıyor.", "Bu tabloya \"gölge AI\" (shadow AI) deniyor: kurumun bilgisi, onayı ve denetimi dışında kullanılan yapay zekâ araçları. Gölge AI aslında bir disiplin sorunu değil, karşılanmamış bir ihtiyacın belirtisi. Bu yazıda neden ortaya çıktığını, hangi riskleri doğurduğunu ve yasaklamak yerine nasıl yönetilebilir hale getirilebileceğini ele alıyoruz."], "sections": [{"heading": "Gölge AI nedir ve kurumlarda nasıl başlar?", "paragraphs": ["Gölge AI, BT envanterinde yer almayan, kurumsal bir sözleşmeyle bağlanmamış ve hiçbir denetim akışına girmeyen her türlü yapay zekâ kullanımını tanımlar. Kişisel aboneliklerle açılan sohbet araçları, tarayıcı eklentileri, telefondaki uygulamalar, bir ekibin kendi imkânlarıyla kurduğu küçük otomasyonlar bu başlığın altına girer. Ortak nokta şudur: kurum, o etkileşimin gerçekleştiğini bilmez.", "Başlangıcı neredeyse her zaman masumdur. Bir toplantı notunu özetlemek, bir e-postayı İngilizceye çevirmek, bir tablo formülünü sormak gibi küçük işlerle başlar. Bu işler kimseye zararlı görünmediği için kimse izin istemeyi de düşünmez.", "Asıl kayma, alışkanlık yerleştikten sonra gelir. Aynı araca bir süre sonra müşteri listesi, fiyat teklifi, kaynak kodu parçası veya personel bilgisi de yapıştırılır. Sınırın nerede aşıldığını fark eden kimse olmaz, çünkü sınırı çizen ve izleyen bir yapı yoktur."]}, {"heading": "Çalışanlar neden kişisel hesaplara yöneliyor?", "paragraphs": ["En yaygın sebep, kurumsal bir alternatifin hiç olmaması ya da erişiminin zor olmasıdır. Talep formu, onay zinciri ve tedarik süreci haftalara yayıldığında, çalışan teslim tarihini bekletmek yerine kendi hesabını açar. Buradaki tercih kural tanımazlık değil, hızdır.", "İkinci sebep daha sinsidir: kurum içi bir araç vardır ama işe yaramaz. Kurumsal belgelere erişmeyen, şirketin kendi terminolojisini bilmeyen, genel geçer cevaplar üreten bir asistan çalışanı ikna etmez. İnsanlar kendilerine gerçekten yardımcı olan aracı kullanır; kurumsal olanı değil.", "Üçüncü sebep, yasakların kendisidir. Kesin bir yasak talebi ortadan kaldırmaz, yalnızca kullanımı şirket cihazından kişisel telefona taşır. Kurum bu noktada hem riski hem de riskin görünürlüğünü aynı anda kaybeder."]}, {"heading": "Gölge AI''ın doğurduğu dört temel risk", "paragraphs": ["Birincisi veri sızıntısıdır. Kişisel bir hesaba girilen veri, kurumun müzakere ettiği kurumsal koşullara değil, çalışanın tek başına kabul ettiği bireysel kullanım koşullarına tabidir. Verinin nerede saklandığı, ne kadar süre tutulduğu ve nasıl işlendiği kurumun kontrolü dışına çıkar; kişisel veri söz konusuysa mesele doğrudan mevzuat uyumu sorununa dönüşür.", "İkincisi denetlenemezliktir. Hangi sorunun sorulduğu, hangi belgenin yüklendiği, hangi modelin yanıt verdiği hiçbir yerde kayıtlı değildir. Bir hata sonradan fark edildiğinde ya da bir iç inceleme başladığında geriye dönüp bakılacak hiçbir iz bulunmaz.", "Üçüncüsü tutarsız yanıtlar, dördüncüsü ise dağınık maliyettir. Aynı politika sorusuna iki farklı departman iki farklı cevap alır ve bu cevaplar zamanla resmî belgelere, tekliflere, müşteri yazışmalarına sızar. Maliyet tarafındaysa onlarca küçük bireysel abonelik masraf kalemlerine dağılır: toplam harcama bilinmez, karşılığında elde edilen fayda hiç ölçülmez."]}, {"heading": "Yasaklamak neden çözüm değil?", "paragraphs": ["Yasak, ihtiyacı değil görünürlüğü yok eder. Kullanım devam eder ama artık kurumun göremediği cihazlarda ve hesaplarda sürer; risk azalmaz, yalnızca ölçülemez hale gelir. Denetim açısından en kötü senaryo budur.", "Yasağın bir de rekabet maliyeti vardır. İşini daha hızlı bitirmenin yolunu bulmuş bir ekibi yavaşlatmak, kısa vadede uyum sağlar gibi görünse de uzun vadede hem verimliliği hem çalışan memnuniyetini aşağı çeker.", "Bu yüzden doğru soru \"yapay zekâ kullanılsın mı\" değildir. Doğru soru şudur: hangi veriyle, hangi yetkiyle, hangi model üzerinden ve hangi kayıtla kullanılsın. Bu dört başlık netleştiği anda konu bir güvenlik tartışması olmaktan çıkıp yönetim meselesine dönüşür."]}, {"heading": "Gölge AI''ı yönetilebilir kılan kurumsal yapay zekâ katmanı", "paragraphs": ["Çözümün özü tek bir giriş kapısı kurmaktır. Çalışan sorusunu tek bir kurumsal arayüzden sorar; arkada hangi modelin çalışacağı, hangi veriye erişileceği ve isteğin nasıl kayda geçeceği kurum tarafından belirlenir. Kullanıcı deneyimi sadeleşirken kurum tarafında görünürlük doğar.", "Bu katmanın ikna edici olması için yanıtların kurumun kendi bilgisine dayanması gerekir. Asistan; prosedürlere, sözleşme şablonlarına, ürün dokümanlarına ve iç politikalara bakarak cevap verdiğinde, dışarıdaki genel amaçlı bir araca gitmenin cazibesi kendiliğinden azalır. HubAI-X gibi kurumsal yapay zekâ platformları tam olarak bu noktayı hedefler: çalışan sorar, asistanlar kurumsal belgelerden yanıtlar, her istek tek ekrandan denetlenir.", "Dört riskin karşılığı da bu katmanda somutlaşır. Rol bazlı yetkilendirme (RBAC) kimin hangi veriye erişeceğini sınırlar, model yönlendirme yanıt tutarlılığını sağlar, bütçe kontrolü harcamayı tek yerde toplar, denetim kaydı ise sonradan geriye bakılabilecek izi üretir."]}, {"heading": "Nereden başlamalı: gölge AI''ı gün ışığına çıkarmak", "paragraphs": ["İlk adım envanterdir ve bu envanter cezalandırıcı olmamalıdır. Kısa bir iç anket, yöneticilerin ekipleriyle yaptığı açık bir konuşma ve mevcut abonelik kalemlerinin gözden geçirilmesi genelde tablonun büyük kısmını ortaya çıkarır. Amaç kimin kuralı çiğnediğini bulmak değil, hangi işlerin yapay zekâya ihtiyaç duyduğunu görmektir.", "İkinci adım, okunabilir bir veri politikasıdır. Hangi veri sınıfının hangi ortamda işlenebileceğini tek sayfada, sade cümlelerle anlatın; kimsenin sonuna kadar okumadığı uzun bir yönerge, pratikte hiç yazılmamış politikayla aynı sonucu verir.", "Üçüncü adım alternatifi gerçekten kullanışlı yapmak ve sonuçları ölçmektir. Tek ekranlı bir platform — HubAI-X bu mantıkla kurgulanmıştır — envanteri zaten kendiliğinden üretir: kimin ne sorduğu, hangi asistanın yanıtladığı ve maliyetin nereye gittiği tek yerden görünür hale gelir. Gölge AI böylece yasaklanarak değil, gün ışığına çıkarılarak çözülür."]}], "takeaways": ["Gölge AI bir disiplin sorunu değil, karşılanmamış bir ihtiyacın göstergesidir; çalışanlar kurumsal alternatif yavaş ya da yetersiz olduğu için kişisel hesaplara yönelir.", "Dört temel risk vardır: veri sızıntısı, denetim izinin bulunmaması, departmanlar arası tutarsız yanıtlar ve dağınık, ölçülemeyen maliyet.", "Yasak talebi değil görünürlüğü yok eder; kullanım şirket cihazından kişisel telefona taşınır ve risk ölçülemez hale gelir.", "Yönetilebilirlik üç bileşene dayanır: tek giriş kapısı, rol bazlı yetkilendirme ve her isteğin denetim kaydı.", "İlk adım cezalandırmayan bir envanter çıkarmak, ikincisi kurumsal alternatifi kişisel hesaptan daha kullanışlı hale getirmektir."], "faq": [{"q": "Gölge AI (shadow AI) nedir?", "a": "Gölge AI, çalışanların kurumun bilgisi, onayı ve denetimi dışında kullandığı yapay zekâ araçlarını tanımlar. Kişisel aboneliklerle açılan sohbet araçları, tarayıcı eklentileri ve ekiplerin kendi imkânlarıyla kurduğu küçük otomasyonlar bu kapsama girer. Ortak özellikleri, BT envanterinde yer almamaları ve hiçbir kayıt bırakmamalarıdır."}, {"q": "Gölge AI''ı tamamen yasaklamak doğru bir strateji mi?", "a": "Yasak, ihtiyacı ortadan kaldırmadığı için genelde beklenen sonucu vermez; kullanım yalnızca kurumun göremediği kişisel cihazlara kayar. Bu durumda risk azalmaz, sadece ölçülemez hale gelir. Daha etkili yaklaşım, kullanımı denetlenebilir bir kurumsal katmana taşımak ve hangi verinin nerede işlenebileceğini net biçimde tanımlamaktır."}, {"q": "Kurumda gölge AI kullanımı nasıl tespit edilir?", "a": "Ağ ve proxy kayıtları, kimlik doğrulama günlükleri ve masraf kalemlerindeki bireysel abonelikler ilk ipuçlarını verir. Bunlara tarayıcı eklentisi envanteri ve ekip yöneticileriyle yapılan açık görüşmeler eklenebilir. Tespit sürecinin cezalandırıcı değil, ihtiyaç anlamaya dönük yürütülmesi çok daha doğru bir tablo çıkarır."}, {"q": "Kurumsal yapay zekâ platformu gölge AI''ı nasıl azaltır?", "a": "Çalışana tek bir giriş kapısı sunarak, dışarıdaki araçlara gitme ihtiyacını ortadan kaldırır. Yanıtlar kurumun kendi belgelerine dayandığı için sonuç kalitesi genel amaçlı araçlardan daha isabetli olur. Arkada rol bazlı yetkilendirme, model yönlendirme, bütçe kontrolü ve denetim kaydı çalıştığı için kullanım aynı anda hem serbest hem izlenebilir hale gelir."}], "cover": "/images/ash-blog-golge-ai.svg", "seoTitle": "Gölge AI: Kurumsal Yapay Zekâ Riskleri", "coverAlt": ""}'::jsonb) on conflict (locale,slug) do nothing;

insert into public.ash_blog_posts(locale,translation_key,slug,status,content) values ('en','golge-ai-kurumsal-yapay-zeka','shadow-ai-enterprise-ai','published','{"slug": "shadow-ai-enterprise-ai", "title": "Shadow AI: The Hidden Risk of Enterprise AI", "metaDescription": "If employees are using AI from personal accounts, shadow AI has already started. We explain its risks, its causes and the path to enterprise AI.", "category": "Enterprise AI", "summary": "Employees using AI tools from personal accounts, in other words shadow AI, isn''t solved by a ban but by a visible, manageable enterprise AI layer. We look at why it happens, its four core risks and the first steps an organization can take.", "readingMinutes": 5, "date": "2026-09-15", "author": {"name": "ASH Team", "role": "Enterprise AI Solutions"}, "intro": ["One evening, one of your employees pastes a contract into an AI tool they''ve logged into with a personal account, just to get a summary. They finish the job quickly, ask nobody, and nobody finds out. This behavior, which could technically count as a policy violation, is repeated many times a day in most organizations.", "This is what''s called shadow AI: AI tools used outside the organization''s knowledge, approval and oversight. Shadow AI isn''t really a discipline problem; it''s a symptom of an unmet need. In this post we look at why it appears, what risks it creates, and how it can be made manageable instead of banned."], "sections": [{"heading": "What is shadow AI, and how does it start in organizations?", "paragraphs": ["Shadow AI covers any use of AI that isn''t in the IT inventory, isn''t tied to a corporate contract and doesn''t pass through any oversight flow. Chat tools opened with personal subscriptions, browser extensions, phone apps and small automations a team has built on its own all fall under this heading. What they have in common: the organization doesn''t know the interaction took place.", "It almost always starts innocently, with small tasks like summarizing meeting notes, translating an email into English or asking about a spreadsheet formula. Because these tasks don''t seem harmful to anyone, nobody thinks of asking permission.", "The real drift comes once the habit has set in. After a while, customer lists, price quotes, snippets of source code or personnel information get pasted into the same tool. Nobody notices where the line was crossed, because there''s no structure that draws and watches that line."]}, {"heading": "Why do employees turn to personal accounts?", "paragraphs": ["The most common reason is that there''s no corporate alternative at all, or that it''s hard to access. When a request form, an approval chain and a procurement process stretch over weeks, the employee opens their own account rather than let a deadline slip. The choice here isn''t defiance; it''s speed.", "The second reason is subtler: there is an internal tool, but it doesn''t help. An assistant that can''t access company documents, doesn''t know the company''s own terminology and produces generic answers won''t convince anyone. People use the tool that genuinely helps them, not the one that''s official.", "The third reason is the ban itself. A strict ban doesn''t remove the demand; it only moves the usage from the company device to a personal phone. At that point the organization loses both the risk and its visibility at the same time."]}, {"heading": "The four core risks of shadow AI", "paragraphs": ["The first is data leakage. Data entered into a personal account is subject not to the corporate terms the organization negotiated, but to the individual terms of use the employee accepted alone. Where the data is stored, how long it''s kept and how it''s processed move out of the organization''s control; when personal data is involved, the matter turns directly into a regulatory compliance issue.", "The second is the lack of auditability. Which question was asked, which document was uploaded and which model answered are recorded nowhere. When an error is discovered later or an internal review begins, there''s no trail to look back at.", "The third is inconsistent answers, and the fourth is scattered cost. Two departments get two different answers to the same policy question, and over time those answers seep into official documents, proposals and customer correspondence. On the cost side, dozens of small individual subscriptions are spread across expense lines: the total spend is unknown and the benefit gained is never measured."]}, {"heading": "Why a ban isn''t the answer", "paragraphs": ["A ban removes visibility, not the need. Usage continues, but now on devices and accounts the organization can''t see; the risk doesn''t shrink, it just becomes unmeasurable. From an oversight perspective, that''s the worst-case scenario.", "A ban also has a competitive cost. Slowing down a team that has found a way to finish its work faster may look like compliance in the short term, but in the long run it drags down both productivity and employee satisfaction.", "So the right question isn''t \"should AI be used?\" The right question is: with which data, with which permissions, through which model and with what record? As soon as these four points are clear, the topic stops being a security debate and becomes a management matter."]}, {"heading": "The enterprise AI layer that makes shadow AI manageable", "paragraphs": ["The essence of the solution is to set up a single front door. Employees ask their questions through one corporate interface; which model runs behind it, which data is accessed and how the request is recorded are decided by the organization. The user experience gets simpler, while the organization gains visibility.", "For this layer to be convincing, answers have to be grounded in the organization''s own knowledge. When the assistant answers by looking at procedures, contract templates, product documentation and internal policies, the appeal of going to an outside general-purpose tool fades on its own. Enterprise AI platforms such as HubAI-X aim at exactly this point: employees ask, assistants answer from company documents, and every request is governed from a single screen.", "The answer to each of the four risks takes concrete form in this layer. Role-based access control (RBAC) limits who can access which data, model routing ensures consistent answers, budget control brings spending into one place, and the audit log creates a trail you can look back on."]}, {"heading": "Where to start: bringing shadow AI into the light", "paragraphs": ["The first step is an inventory, and that inventory shouldn''t be punitive. A short internal survey, an open conversation between managers and their teams, and a review of existing subscription expenses usually reveal most of the picture. The goal isn''t to find who broke the rules, but to see which tasks need AI.", "The second step is a readable data policy. Explain on a single page, in plain sentences, which class of data can be processed in which environment; a long guideline that nobody reads to the end has, in practice, the same effect as a policy that was never written.", "The third step is to make the alternative genuinely useful and to measure the results. A single-screen platform, which is how HubAI-X is designed, produces the inventory on its own: who asked what, which assistant answered and where the cost is going all become visible in one place. Shadow AI is solved not by banning it, but by bringing it into the light."]}], "takeaways": ["Shadow AI isn''t a discipline problem but a sign of an unmet need; employees turn to personal accounts because the corporate alternative is slow or inadequate.", "There are four core risks: data leakage, no audit trail, inconsistent answers across departments, and scattered, unmeasurable cost.", "A ban removes visibility, not demand; usage moves from the company device to a personal phone and the risk becomes unmeasurable.", "Manageability rests on three components: a single front door, role-based access control and an audit record for every request.", "The first step is a non-punitive inventory; the second is making the corporate alternative more useful than a personal account."], "faq": [{"q": "What is shadow AI?", "a": "Shadow AI refers to AI tools employees use outside the organization''s knowledge, approval and oversight. Chat tools opened with personal subscriptions, browser extensions and small automations teams build on their own all fall into this category. What they have in common is that they aren''t in the IT inventory and leave no record."}, {"q": "Is banning shadow AI entirely the right strategy?", "a": "A ban usually doesn''t deliver the expected result because it doesn''t remove the need; usage simply shifts to personal devices the organization can''t see. The risk doesn''t shrink, it just becomes unmeasurable. A more effective approach is to move usage into an auditable enterprise layer and clearly define which data can be processed where."}, {"q": "How can shadow AI use be detected in an organization?", "a": "Network and proxy logs, authentication logs and individual subscriptions in expense items give the first clues. A browser extension inventory and open conversations with team managers can be added to these. Running the detection process to understand needs rather than to punish produces a much more accurate picture."}, {"q": "How does an enterprise AI platform reduce shadow AI?", "a": "By offering employees a single front door, it removes the need to go to outside tools. Because answers are grounded in the organization''s own documents, the results are more accurate than those of general-purpose tools. With role-based access control, model routing, budget control and audit logging running behind the scenes, usage becomes both unrestricted and traceable at the same time."}], "cover": "/images/ash-blog-golge-ai.en.svg", "seoTitle": "Shadow AI: Risks of Enterprise AI", "coverAlt": ""}'::jsonb) on conflict (locale,slug) do nothing;

insert into public.ash_blog_posts(locale,translation_key,slug,status,content) values ('tr','masraf-yonetimi-neden-tikanir','masraf-yonetimi-neden-tikanir','published','{"slug": "masraf-yonetimi-neden-tikanir", "title": "Masraf Yönetimi Neden Tıkanır? Harcama Otomasyonunun Asıl Farkı", "metaDescription": "Fiş toplama, manuel veri girişi ve ay sonunda fark edilen politika ihlalleri masraf yönetimini tıkıyor. Harcama otomasyonunun asıl farkı nerede başlıyor?", "category": "Harcama Yönetimi", "summary": "Fiş toplamadan onay zincirine, kurumsal masraf sürecinin tıkandığı noktaları ve harcama otomasyonunun asıl farkını ele alıyoruz: kuralları kayıt anında uygulamak ve denetlenebilir bir iz bırakmak.", "readingMinutes": 4, "date": "2026-08-26", "author": {"name": "ASH Ekibi", "role": "Finansal Süreç Otomasyonu"}, "intro": ["Masraf yönetimi, birçok kurumda kimsenin gönüllü olarak sahiplenmediği bir süreçtir. Çalışan fişini biriktirir, yönetici onay kuyruğunda sırasını bekler, finans ekibi ay sonunda yığılan kayıtlarla karşılaşır. Herkes kendi adımını doğru yaptığını düşünür; buna rağmen süreç her dönem aynı yerde takılır.", "Sorunun kaynağı çoğunlukla dikkatsizlik değil, sürecin kurgusudur. Harcama bilgisi oluştuğu anda yakalanmadığında, eksik veya kurala aykırı her kayıt zincirin sonuna kadar taşınır ve orada düzeltilmeye çalışılır. Bu yazıda masraf sürecinin tam olarak nerede tıkandığına ve harcama otomasyonunun neyi gerçekten değiştirdiğine bakıyoruz."], "sections": [{"heading": "Masraf süreci tam olarak nerede tıkanır?", "paragraphs": ["İlk tıkanma noktası genellikle fişin kendisidir. Harcama yapıldığı anda oluşan belge, çantada veya cüzdanda günlerce bekler. Harcamanın gerçekleştiği an ile kayda geçtiği an arasında bir boşluk açılır ve süreçteki tüm gecikme bu boşluktan beslenir.", "Bu boşluk büyüdükçe bilginin kendisi kaybolur. Fişin üzerindeki tutar okunabilir durumda kalsa bile, harcamanın hangi projeye, hangi müşteri ziyaretine veya hangi bütçe kalemine ait olduğu artık hatırlanmaz. Çalışan tahmin ederek doldurur, finans ekibi de bu tahmini doğrulamak için geri döner.", "İkinci tıkanma ise takvimden kaynaklanır. Herkesin kaydını dönem sonunda girmesi, finans ekibinin tüm hacmi tek bir dar zaman aralığında karşılaması anlamına gelir. Aynı işi ayın tamamına yayarak yapmak mümkünken, süreç kendi kendini bir tepe noktasına sıkıştırır."]}, {"heading": "Manuel veri girişi ve mükerrer kayıtların görünmeyen maliyeti", "paragraphs": ["Manuel veri girişi yalnızca zaman tüketmez, hata da üretir. Tutarın yanlış hanesi, karışan tarih, seçilmeyen KDV oranı veya boş bırakılan masraf merkezi, kaydı ilerletmek yerine geri döndürür. Her geri dönüş, süreci baştan başlatan küçük bir tur demektir.", "Mükerrer kayıtlar ise daha sinsidir. Aynı harcama hem kurumsal kart ekstresinden hem de elle girilen fişten sisteme düşebilir; bir ekip yemeğinde aynı belge birden fazla katılımcı tarafından yüklenebilir. Bu kayıtlar kural olarak birbirine çok benzediği için gözle ayıklanması zordur.", "Mükerrer bir kayıt onaylandıktan sonra fark edildiğinde maliyet katlanır. Düzeltme artık tek bir alanın değiştirilmesi değil, muhasebe kaydının geri alınması, kapatılmış dönemin tekrar açılması ve çalışana durumun izah edilmesi anlamına gelir."]}, {"heading": "Politika ihlalleri neden hep ay sonunda görülüyor?", "paragraphs": ["Çoğu kurumda harcama politikası bir belgede yaşar, süreçte değil. Kurallar intranette duran bir dosyada net biçimde yazılıdır; ancak çalışan harcamayı yaparken o dosyayı açmaz, kaydı girerken de kimse ona kuralı hatırlatmaz. Politika, ancak kontrol aşamasında sahneye çıkar.", "Kontrol geç geldiğinde elde kalan seçenekler iyi değildir. Kaydı reddetmek, harcamayı çoktan yapmış bir çalışanı maliyetle baş başa bırakır ve sürece karşı direnç oluşturur. Kaydı geçirmek ise kuralı fiilen işlevsiz hale getirir; bir kez esnetilen limit, sonraki dönemde referans noktası olur.", "Asıl mesele kuralın sertliği değil, kontrolün zamanlamasıdır. Aynı kural, harcama kaydı oluşurken uygulandığında bir uyarıdır; dönem sonunda uygulandığında ise bir ihtilaftır."]}, {"heading": "Asıl fark: kuralları kayıt anında uygulamak", "paragraphs": ["Harcama otomasyonu denince akla ilk gelen şey fiş okumaktır. Bir belgeden tutarı, tarihi ve satıcıyı çıkarmak süreci hızlandırır; ancak bu yalnızca giriş kapısıdır. Yanlış kategoriye yazılmış veya limiti aşan bir harcama, otomatik okunduğunda da yanlış kalır.", "Gerçek fark, kurumun kendi kurallarının kaydın oluştuğu anda çalışmasıdır. Kategori limiti, günlük konaklama üst sınırı, zorunlu proje kodu, belge tipi ve KDV beklentisi gibi kontroller kayıt kapanmadan önce devreye girer. Çalışan uyarıyı, harcamayı hâlâ hatırladığı anda görür ve düzeltmeyi kendisi yapar.", "Masraf-X''in yaklaşımı da tam olarak bu sırayı izler: fişi kayda çevirir ve şirket kurallarını kaydın oluştuğu anda uygular. Böylece kontrol, dönem sonunda yapılan bir temizlik işi olmaktan çıkıp sürecin normal bir parçası haline gelir."]}, {"heading": "Onay zinciri neden uzar, nasıl kısalır?", "paragraphs": ["Onay zincirinin uzaması genellikle yöneticinin ilgisizliğinden değil, eksik bağlamdan kaynaklanır. Ekranda yalnızca bir tutar ve kısa bir açıklama gören yönetici, onaylamadan önce sormak zorunda kalır: Bu harcama kime ait, hangi işin parçası, belgesi nerede?", "Her soru bir tur demektir. Yönetici sorar, çalışan yanıtlar, kayıt tekrar kuyruğa girer. Bu gidiş gelişler tek tek küçük görünse de, dönem boyunca biriktiğinde onay süresinin büyük bölümünü oluşturur.", "Bağlam kaydın içinde hazır olduğunda onay tek bir karara iner. Kural motoru kurala uyan kayıtları zaten ayıklamışsa, yöneticinin dikkati yalnızca gerçek istisnalara kalır; geri kalanı akışın içinde ilerler."]}, {"heading": "Denetlenebilir iz ve onaylı masrafın ERP''ye taşınması", "paragraphs": ["Bir denetim sorusu her zaman aynı biçimde gelir: Bu harcama neden ve kimin kararıyla onaylandı? Cevap e-postalara, mesajlaşma uygulamalarına ve kişisel not defterlerine dağılmışsa, süreç hızlı olsa bile denetlenebilir değildir.", "Denetlenebilir iz, kaydın kendi yanında durmalıdır. Hangi kuralın çalıştığı, hangi uyarının verildiği, istisnanın kim tarafından ve hangi gerekçeyle tanındığı, onayın ne zaman düştüğü aynı kaydın geçmişinde görünmelidir. Bu iz, hem iç kontrol hem de mali müşavir ve denetçi soruları için tek bir doğruluk kaynağı oluşturur.", "Sürecin son adımı ise muhasebeleştirmedir. Onaylı masraf ERP''ye elle aktarılmaya devam ettiği sürece, önceki adımlarda kazanılan zaman burada geri verilir; Masraf-X gibi çözümlerde bu aktarımın akışın doğal bir parçası olması, otomasyonun baştan sona anlamlı hale gelmesini sağlar."]}], "takeaways": ["Masraf sürecindeki gecikmenin kaynağı, harcamanın yapıldığı an ile kayda geçtiği an arasındaki boşluktur.", "Manuel veri girişi hata üretir; mükerrer kayıtlar ise onaydan sonra fark edildiğinde çok daha pahalıya mal olur.", "Politika belgede değil, kayıt akışının içinde yaşamalıdır; geç uygulanan kural uyarı değil ihtilaf üretir.", "Fiş okuma otomasyonun yalnızca giriş kapısıdır; asıl fark kuralların kayıt anında çalışmasıdır.", "Onay süresini kısaltan şey baskı değil, kararın bağlamının kaydın içinde hazır olmasıdır.", "Denetlenebilir iz ve ERP''ye otomatik aktarım olmadan, kazanılan zaman sürecin sonunda geri verilir."], "faq": [{"q": "Harcama otomasyonu sadece fiş okumaktan mı ibaret?", "a": "Hayır. Fiş okuma, belgedeki tutar, tarih ve satıcı gibi bilgileri kayda çevirerek süreci hızlandırır; ancak tek başına doğruluk sağlamaz. Yanlış kategoriye yazılmış veya limiti aşan bir harcama otomatik okunduğunda da hatalı kalır. Asıl fark, kurum kurallarının kaydın oluştuğu anda uygulanmasıyla ortaya çıkar."}, {"q": "Politika ihlalleri kayıt anında nasıl engellenir?", "a": "Kurumun harcama politikası, insan hafızasına bırakılan bir belge olmaktan çıkarılıp sistemin kontrol ettiği kurallara dönüştürülür. Kategori limitleri, zorunlu alanlar, belge tipi ve proje kodu gibi kontroller kayıt kapanmadan önce çalışır. Çalışan uyarıyı harcamayı hâlâ hatırladığı anda görür ve düzeltmeyi kendisi yapabilir."}, {"q": "Masraf yönetiminde onay süresi neden uzar?", "a": "Onay süresini uzatan temel etken eksik bağlamdır. Yönetici harcamanın gerekçesini, belgesini veya ait olduğu işi göremediğinde onaylamadan önce sormak zorunda kalır ve her soru kaydı yeniden kuyruğa sokar. Bağlam kaydın içinde hazır olduğunda ve kurala uyan kayıtlar önceden ayıklandığında, yöneticinin dikkati yalnızca istisnalara kalır."}, {"q": "Mükerrer masraf kayıtları nasıl önlenir?", "a": "Mükerrer kayıtlar genellikle aynı harcamanın hem kurumsal kart hareketinden hem de elle yüklenen fişten girilmesiyle ya da aynı belgenin birden fazla katılımcı tarafından yüklenmesiyle oluşur. Bunları gözle ayıklamak zordur, çünkü kayıtlar birbirine çok benzer. Kayıtların tek bir akışta toplanması ve benzer tutar, tarih ve belge bilgisinin kayıt anında kontrol edilmesi, sorunun onaydan sonraya kalmasını engeller."}, {"q": "Onaylanan masraf verisi ERP ile nasıl bütünleşir?", "a": "Onay tamamlandıktan sonra kaydın muhasebeleştirilmesi sürecin son adımıdır. Bu aktarım elle yapıldığı sürece, önceki adımlarda kazanılan zaman burada geri verilir ve yeni hata riski doğar. Onaylı masrafın ERP''ye akışın doğal bir parçası olarak taşınması, otomasyonun baştan sona anlam kazanmasını sağlar."}], "cover": "/images/ash-blog-masraf.svg", "seoTitle": "Masraf Yönetimi ve Harcama Otomasyonu", "coverAlt": ""}'::jsonb) on conflict (locale,slug) do nothing;

insert into public.ash_blog_posts(locale,translation_key,slug,status,content) values ('en','masraf-yonetimi-neden-tikanir','why-expense-management-gets-stuck','published','{"slug": "why-expense-management-gets-stuck", "title": "Why Does Expense Management Get Stuck? The Real Difference in Spend Automation", "metaDescription": "Collecting receipts, manual data entry and policy violations spotted at month-end clog expense management. Where does the real difference of spend automation begin?", "category": "Spend Management", "summary": "From collecting receipts to the approval chain, we look at where the corporate expense process gets stuck and at the real difference spend automation makes: applying rules at the moment of entry and leaving an auditable trail.", "readingMinutes": 4, "date": "2026-08-26", "author": {"name": "ASH Team", "role": "Financial Process Automation"}, "intro": ["In many organizations, expense management is a process nobody volunteers to own. Employees collect their receipts, managers wait their turn in the approval queue, and the finance team faces a pile of records at month-end. Everyone believes they did their own step right; even so, the process gets stuck in the same place every period.", "The source of the problem is usually not carelessness, but how the process is designed. When spending information isn''t captured the moment it''s created, every incomplete or non-compliant record is carried to the end of the chain and fixed there. In this post we look at exactly where the expense process gets stuck and what spend automation really changes."], "sections": [{"heading": "Where exactly does the expense process get stuck?", "paragraphs": ["The first bottleneck is usually the receipt itself. The document created at the moment of spending sits in a bag or wallet for days. A gap opens between the moment the expense happens and the moment it''s recorded, and every delay in the process feeds on that gap.", "As the gap grows, the information itself gets lost. Even if the amount on the receipt is still legible, nobody remembers which project, customer visit or budget line the expense belonged to. The employee fills it in by guessing, and the finance team goes back to verify that guess.", "The second bottleneck comes from the calendar. If everyone enters their records at the end of the period, the finance team has to absorb the whole volume in one narrow window. Although the same work could be spread across the month, the process squeezes itself into a peak."]}, {"heading": "The hidden cost of manual data entry and duplicate records", "paragraphs": ["Manual data entry doesn''t just consume time; it also produces errors. A misplaced digit in the amount, a mixed-up date, an unselected VAT rate or an empty cost center sends the record back instead of moving it forward. Every return is a small loop that restarts the process.", "Duplicate records are more insidious. The same expense can land in the system both from the corporate card statement and from a manually entered receipt; after a team dinner, the same document can be uploaded by more than one attendee. Because these records usually look very similar, they''re hard to weed out by eye.", "When a duplicate is only noticed after approval, the cost multiplies. The fix is no longer a change to a single field; it means reversing the accounting entry, reopening a closed period and explaining the situation to the employee."]}, {"heading": "Why are policy violations always spotted at month-end?", "paragraphs": ["In most organizations, the spending policy lives in a document, not in the process. The rules are clearly written in a file on the intranet; but employees don''t open that file when they spend, and nobody reminds them of the rule when they enter the record. The policy only takes the stage at the checking step.", "When the check comes late, the remaining options aren''t good. Rejecting the record leaves an employee who has already spent the money alone with the cost and builds resistance to the process. Letting it through makes the rule effectively useless; a limit stretched once becomes the reference point for the next period.", "The real issue isn''t how strict the rule is, but when the check happens. The same rule is a warning when applied while the expense record is being created; applied at the end of the period, it''s a dispute."]}, {"heading": "The real difference: applying rules at the moment of entry", "paragraphs": ["When people hear spend automation, the first thing that comes to mind is reading receipts. Extracting the amount, date and vendor from a document speeds up the process; but that''s only the entrance. An expense recorded under the wrong category or over the limit stays wrong even when it''s read automatically.", "The real difference is that the organization''s own rules run the moment the record is created. Checks such as category limits, a daily accommodation cap, a mandatory project code, document type and expected VAT kick in before the record is closed. Employees see the warning while they still remember the expense, and make the correction themselves.", "Masraf-X follows exactly this order: it turns the receipt into a record and applies company rules the moment the record is created. That way, checking stops being a clean-up job at the end of the period and becomes a normal part of the process."]}, {"heading": "Why does the approval chain get longer, and how can it be shortened?", "paragraphs": ["A long approval chain usually comes not from managers'' lack of interest, but from missing context. A manager who sees only an amount and a short description on screen has to ask before approving: whose expense is this, what work is it part of, where is the document?", "Every question is another round. The manager asks, the employee answers, the record goes back into the queue. These back-and-forths look small one by one, but accumulated over the period they make up most of the approval time.", "When the context is already in the record, approval comes down to a single decision. If the rules engine has already filtered out the compliant records, the manager''s attention is left only for genuine exceptions; the rest moves along within the flow."]}, {"heading": "An auditable trail and moving approved expenses into the ERP", "paragraphs": ["An audit question always arrives in the same form: why, and on whose decision, was this expense approved? If the answer is scattered across emails, messaging apps and personal notebooks, the process isn''t auditable, however fast it is.", "The auditable trail should sit right next to the record. Which rule ran, which warning was issued, who accepted the exception and on what grounds, and when the approval came through should all be visible in the same record''s history. This trail becomes a single source of truth for both internal control and questions from accountants and auditors.", "The final step of the process is accounting. As long as approved expenses are still transferred to the ERP by hand, the time saved in the earlier steps is given back here; in solutions like Masraf-X, making this transfer a natural part of the flow is what makes automation meaningful from start to finish."]}], "takeaways": ["The delay in the expense process comes from the gap between the moment an expense happens and the moment it''s recorded.", "Manual data entry produces errors, and duplicate records cost far more when they''re only noticed after approval.", "The policy should live inside the record flow, not in a document; a rule applied late produces a dispute, not a warning.", "Receipt reading is only the entrance to automation; the real difference is rules running at the moment of entry.", "What shortens approval time isn''t pressure, but having the context for the decision ready inside the record.", "Without an auditable trail and automatic transfer to the ERP, the time you save is given back at the end of the process."], "faq": [{"q": "Is spend automation just about reading receipts?", "a": "No. Receipt reading speeds up the process by turning information on the document, such as amount, date and vendor, into a record; but on its own it doesn''t ensure accuracy. An expense recorded under the wrong category or over the limit stays wrong even when read automatically. The real difference comes from applying company rules at the moment the record is created."}, {"q": "How can policy violations be prevented at the moment of entry?", "a": "The company''s spending policy stops being a document left to human memory and becomes rules checked by the system. Checks such as category limits, mandatory fields, document type and project code run before the record is closed. Employees see the warning while they still remember the expense and can make the correction themselves."}, {"q": "Why does approval take so long in expense management?", "a": "The main factor that lengthens approval is missing context. When a manager can''t see the reason for the expense, its document or the work it belongs to, they have to ask before approving, and every question sends the record back into the queue. When the context is ready in the record and compliant records have been filtered out in advance, the manager''s attention is left only for exceptions."}, {"q": "How can duplicate expense records be prevented?", "a": "Duplicates usually arise when the same expense is entered both from a corporate card transaction and from a manually uploaded receipt, or when the same document is uploaded by more than one attendee. They''re hard to weed out by eye because the records look very similar. Collecting records in a single flow and checking similar amount, date and document details at the moment of entry keeps the problem from surfacing only after approval."}, {"q": "How does approved expense data integrate with the ERP?", "a": "Once approval is complete, posting the record to accounting is the final step of the process. As long as this transfer is done by hand, the time saved in the earlier steps is given back here and a new risk of error appears. Moving approved expenses into the ERP as a natural part of the flow is what makes automation meaningful from start to finish."}], "cover": "/images/ash-blog-masraf.en.svg", "seoTitle": "Expense Management and Spend Automation", "coverAlt": ""}'::jsonb) on conflict (locale,slug) do nothing;

insert into public.ash_blog_posts(locale,translation_key,slug,status,content) values ('tr','sap-yapay-zeka-abap-gelistirme','sap-yapay-zeka-abap-gelistirme','published','{"slug": "sap-yapay-zeka-abap-gelistirme", "title": "SAP Yapay Zekâ: ABAP Geliştirmede Gerçekte Ne Değişir", "metaDescription": "SAP yapay zekâ girişimlerinde asıl fark ABAP geliştirme ve birinci seviye destekte görülür. Z objeleri, kurum standartları ve onay neden belirleyici?", "category": "SAP ve Yapay Zekâ", "summary": "SAP ekiplerinde yapay zekânın asıl etkisi birinci seviye destek yükünde ve tekrarlayan ABAP geliştirme taleplerinde görünür. Genel amaçlı modellerin Z objeleri karşısında neden yetersiz kaldığını ve üretilen her geliştirmenin neden onaydan geçmesi gerektiğini ele alıyoruz.", "readingMinutes": 4, "date": "2026-09-04", "author": {"name": "ASH Ekibi", "role": "SAP Çözümleri Birimi"}, "intro": ["SAP yapay zekâ başlığı çoğu kurumda aynı yerden açılır: ekip yetişemiyordur, talep kuyruğu uzamıştır ve herkes bir kısayol arar. Oysa bu ekiplerde günü asıl tüketen şey tek tek zor işler değil, aynı işin defalarca tekrarlanmasıdır.", "Bu yazıda yapay zekânın SAP ekiplerinde gerçekte neyi değiştirdiğine bakıyoruz: birinci seviye destek yükü, tekrarlayan ABAP geliştirme talepleri, genel amaçlı modellerin Z objeleri karşısında neden takıldığı ve üretilen her çıktının neden onaydan geçmesi gerektiği."], "sections": [{"heading": "SAP ekiplerinde zaman nereye gidiyor?", "paragraphs": ["Bir SAP ekibinin takvimine bakıldığında iş genellikle üç yığına ayrılır: kullanıcıdan gelen günlük destek talepleri, değişiklik talepleri ve uzun soluklu projeler. İlk iki yığın kesintisiz akar; üçüncüsü ise çoğu zaman geriye kalan zamandan beslenir.", "Asıl sorun, akan işin çoğunlukla yeni olmamasıdır. Aynı hata mesajı farklı kullanıcılardan tekrar tekrar gelir, aynı rapor ihtiyacı birkaç alan farkıyla yeniden yazılır. Ekibin uzmanlığı, uzmanlık gerektirmeyen işe harcanır.", "Yapay zekânın bu tabloda anlamlı olduğu yer de tam burasıdır. Kıymetli olan, zor bir problemi tek başına çözmesi değil; tekrar eden işin uzmanın masasına gelmeden karşılanabilmesidir."]}, {"heading": "Birinci seviye destek: tekrarın görünmeyen maliyeti", "paragraphs": ["Birinci seviye talepler tek tek bakıldığında küçüktür: bir yetki hatası, bir hesap tayini uyarısı, kapanmayan bir belge, kullanıcının bulamadığı bir alan. Her biri birkaç dakika sürer, ama maliyeti dakikayla ölçülmez.", "Derin odak gerektiren bir işten koparılıp beş dakikalık bir soruya bakmak, pratikte çok daha uzun bir kesintidir. Gün içinde bu kesintiler üst üste bindiğinde ekibin proje kapasitesi görünmeden erir.", "Yapay zekâ destekli bir asistan bu taleplerin bir bölümünü kaynağında karşılayabilir: hata mesajını yorumlar, ilgili yapılandırmayı işaret eder, benzer geçmiş talepleri hatırlar. Geriye gerçekten uzman gerektiren talepler kalır."]}, {"heading": "Tekrarlayan ABAP geliştirme talepleri neden birikir?", "paragraphs": ["ABAP geliştirme taleplerinin önemli bir bölümü yapısal olarak birbirine benzer: bir sorgu, birkaç tablo birleşimi, bir yetki kontrolü, bir çıktı ekranı. Yeni olan şey iş ihtiyacıdır, teknik kalıp değil.", "Buna rağmen her talep baştan başlar; analiz, tasarım, geliştirme, test ve taşıma adımları yeniden kurulur. Takvimi uzatan şey çoğu zaman kodu yazmak değil, kuyruğa girip sıra beklemektir.", "Kalıbın tekrar ettiği yerde yapay zekâ gerçek bir hızlanma sağlar. İhtiyacı doğal dille tarif etmek ile incelemeye hazır bir taslak geliştirme arasındaki mesafe kısalır; ekip yazmak yerine değerlendirmeye odaklanır."]}, {"heading": "Genel amaçlı modeller Z objelerinde neden takılır?", "paragraphs": ["Genel amaçlı bir dil modeli ABAP sözdizimini bilir; standart tabloları, yaygın kalıpları ve belgelenmiş davranışları tanır. Bilmediği tek şey sizin sisteminizdir.", "Kurumsal SAP ortamları yıllar içinde kendi sözlüğünü üretir: Z tabloları, Z sınıfları, özel isimlendirme kuralları, kurum içi geliştirme standartları ve yeniden kullanılması beklenen mevcut objeler. Bunların hiçbiri genel eğitim verisinde yer almaz.", "Sonuç tanıdıktır: teknik olarak doğru görünen ama ortamınıza ait olmayan kod. Derlenir, hatta çalışır; ancak mevcut bir sınıfı yeniden kullanmaz, isimlendirme kuralınıza uymaz, yetki kontrolünüzü atlar. Kazanılan zaman uyarlama işine geri döner."]}, {"heading": "Kurumun kendi sistemini girdi alan yaklaşım", "paragraphs": ["Farkı yaratan şey modelin kendisi değil, modele ne verdiğinizdir. Sistemdeki Z objeleri, mevcut geliştirmeler ve kurum içi standartlar girdi olarak sunulduğunda üretilen çıktı da ortamınıza ait hale gelir.", "Bu yaklaşımda asistan sıfırdan yazmak yerine önce bakar: bu ihtiyacı karşılayan bir obje zaten var mı, hangi sınıf yeniden kullanılabilir, hangi standart uygulanmalı. SAPAI-X''in çalışma biçimi de buna dayanır; çıktı, kurumun mevcut mimarisinden türetilir.", "Yan fayda, belgelenmemiş bilginin yeniden erişilebilir olmasıdır. Yıllar önce yazılmış bir Z objesinin bugün ne yaptığı ve bir değişikliğin nereye dokunacağı, sorulabilir bir şeye dönüşür."]}, {"heading": "Onay ve denetim neden pazarlık konusu değil?", "paragraphs": ["Üretim SAP sistemi deneme yapılacak bir yer değildir. Yapay zekâ ne kadar isabetli çalışırsa çalışsın, bir geliştirmenin canlıya çıkması insan onayından geçmelidir.", "Bu yüzden değerlendirmede sorulması gereken soru \"ne kadar hızlı üretiyor\" değil, \"ürettiğini nasıl gösteriyor\"dur: hangi objeleri referans aldı, neyi değiştirdi, hangi standardı uyguladı, kim onayladı. Bir aracın izlenebilirliği, hızının kendisinden daha belirleyicidir.", "Denetim kaydı aynı zamanda güvenin inşa edildiği yerdir. Ekip üretilen çıktıyı gözden geçirdikçe hangi işlerde asistana daha çok alan bırakacağını, hangi işlerde kontrolü sıkı tutacağını öğrenir."]}], "takeaways": ["SAP ekiplerinde asıl yük tek tek zor işler değil; tekrarlayan destek talepleri ve birbirine benzeyen ABAP geliştirme istekleridir.", "Genel amaçlı modeller ABAP sözdizimini bilir, sizin Z objelerinizi ve kurum standartlarınızı bilmez; bu yüzden ürettikleri kod ek uyarlama işi doğurur.", "Fark modelden değil model girdisinden gelir: mevcut objeler, geliştirmeler ve standartlar girdi olduğunda çıktı da ortamınıza oturur.", "Hız tek başına yeterli değildir; hangi objenin referans alındığı ve kimin onayladığı görünmüyorsa kazanç kalıcı olmaz.", "Üretim sistemine giden her geliştirme insan onayından ve denetim kaydından geçmelidir."], "faq": [{"q": "SAP yapay zekâ çözümleri ABAP geliştiricilerin yerini alır mı?", "a": "Hayır; değişen şey işin dağılımıdır. Tekrarlayan kalıpların taslağı otomatikleşir, geliştiricinin zamanı tasarıma, gözden geçirmeye ve iş kuralı doğruluğuna kayar. Üretime çıkan kodun sorumluluğu ekipte kalır."}, {"q": "Genel amaçlı bir yapay zekâ asistanı ABAP geliştirme için yeterli olmaz mı?", "a": "Sözdizimi için çoğu zaman yeterlidir, ortamınız için değildir. Z objelerinizi, isimlendirme kurallarınızı ve kurum içi geliştirme standartlarınızı bilmediği için üretilen kodu sisteminize uyarlama işi yine ekibinize kalır."}, {"q": "Yapay zekânın ürettiği ABAP kodu doğrudan canlıya alınabilir mi?", "a": "Alınmamalıdır. Üretilen geliştirme, mevcut değişiklik süreciniz gibi gözden geçirme, test ve onay adımlarından geçmelidir. Asistanın rolü bu süreci hızlandırmaktır, atlamak değil."}, {"q": "Z objeleri belgelenmemişse yapay zekâ yine de işe yarar mı?", "a": "Belgelenmemiş olması okunamaz olduğu anlamına gelmez. Sistemdeki objelerin yapısını girdi alan bir yaklaşım, bir objenin bugün ne yaptığını ve yapılacak bir değişikliğin nereye dokunacağını görünür kılabilir."}], "cover": "/images/ash-blog-sap-ai.svg", "seoTitle": "SAP Yapay Zekâ ve ABAP Geliştirme", "coverAlt": ""}'::jsonb) on conflict (locale,slug) do nothing;

insert into public.ash_blog_posts(locale,translation_key,slug,status,content) values ('en','sap-yapay-zeka-abap-gelistirme','sap-ai-abap-development','published','{"slug": "sap-ai-abap-development", "title": "SAP AI: What Really Changes in ABAP Development", "metaDescription": "In SAP AI initiatives, the real difference shows up in ABAP development and first-level support. Why are Z objects, company standards and approval decisive?", "category": "SAP and AI", "summary": "In SAP teams, the real impact of AI shows up in the first-level support load and in recurring ABAP development requests. We look at why general-purpose models fall short with Z objects, and why every generated development must go through approval.", "readingMinutes": 4, "date": "2026-09-04", "author": {"name": "ASH Team", "role": "SAP Solutions Unit"}, "intro": ["In most organizations, the SAP AI conversation starts from the same place: the team can''t keep up, the request queue is growing and everyone is looking for a shortcut. Yet what really eats up these teams'' days isn''t a handful of hard problems; it''s the same work being repeated again and again.", "In this post we look at what AI actually changes in SAP teams: the first-level support load, recurring ABAP development requests, why general-purpose models get stuck on Z objects, and why every output must go through approval."], "sections": [{"heading": "Where does an SAP team''s time go?", "paragraphs": ["Look at an SAP team''s calendar and the work usually falls into three piles: day-to-day support requests from users, change requests and long-running projects. The first two piles flow without pause; the third usually lives on whatever time is left.", "The real problem is that most of the flowing work isn''t new. The same error message comes in again and again from different users, and the same report is rewritten with a few different fields. The team''s expertise is spent on work that doesn''t require expertise.", "This is exactly where AI makes sense. What matters isn''t that it can solve a hard problem on its own; it''s that recurring work can be handled before it ever reaches an expert''s desk."]}, {"heading": "First-level support: the hidden cost of repetition", "paragraphs": ["Taken one by one, first-level requests are small: an authorization error, an account assignment warning, a document that won''t close, a field the user can''t find. Each takes a few minutes, but the cost isn''t measured in minutes.", "Being pulled out of deep-focus work to look at a five-minute question is, in practice, a much longer interruption. When these interruptions stack up over the day, the team''s project capacity quietly melts away.", "An AI-powered assistant can handle part of these requests at the source: it interprets the error message, points to the relevant configuration and recalls similar past requests. What''s left are the requests that genuinely need an expert."]}, {"heading": "Why do recurring ABAP development requests pile up?", "paragraphs": ["A large share of ABAP development requests are structurally similar: a query, a few table joins, an authorization check, an output screen. What''s new is the business need, not the technical pattern.", "Even so, every request starts from scratch; analysis, design, development, testing and transport are set up all over again. What stretches the timeline is usually not writing the code, but joining the queue and waiting for a turn.", "Where the pattern repeats, AI delivers a real speed-up. The distance between describing a need in natural language and a draft development ready for review gets shorter; the team focuses on evaluating instead of writing."]}, {"heading": "Why do general-purpose models get stuck on Z objects?", "paragraphs": ["A general-purpose language model knows ABAP syntax; it recognizes standard tables, common patterns and documented behavior. The one thing it doesn''t know is your system.", "Over the years, enterprise SAP environments build up their own vocabulary: Z tables, Z classes, custom naming rules, in-house development standards and existing objects that are expected to be reused. None of this is in general training data.", "The result is familiar: code that looks technically correct but doesn''t belong in your environment. It compiles, it may even run; but it doesn''t reuse an existing class, doesn''t follow your naming convention and skips your authorization check. The time saved goes straight back into adapting it."]}, {"heading": "An approach that takes the organization''s own system as input", "paragraphs": ["What makes the difference isn''t the model itself, but what you give the model. When the Z objects in the system, existing developments and in-house standards are provided as inputs, the output also becomes part of your environment.", "In this approach, the assistant looks before it writes: is there already an object that meets this need, which class can be reused, which standard should be applied? This is also how SAPAI-X works; the output is derived from the organization''s existing architecture.", "A side benefit is that undocumented knowledge becomes accessible again. What a Z object written years ago does today, and where a change will have an impact, becomes something you can ask about."]}, {"heading": "Why approval and auditability are non-negotiable", "paragraphs": ["A production SAP system is not a place for experiments. However accurate the AI is, a development must go through human approval before it goes live.", "That''s why the question to ask in an evaluation isn''t \"how fast does it produce?\" but \"how does it show what it produced?\": which objects it referenced, what it changed, which standard it applied, who approved it. A tool''s traceability matters more than its speed.", "The audit trail is also where trust is built. As the team reviews the generated output, it learns where to give the assistant more room and where to keep a tight grip."]}], "takeaways": ["The real load on SAP teams isn''t a few hard problems; it''s recurring support requests and ABAP development requests that look alike.", "General-purpose models know ABAP syntax but not your Z objects or company standards, so the code they produce creates extra adaptation work.", "The difference comes from the model''s input, not the model: when existing objects, developments and standards are the input, the output fits your environment.", "Speed alone isn''t enough; if you can''t see which object was referenced and who approved it, the gain won''t last.", "Every development heading to the production system must go through human approval and an audit trail."], "faq": [{"q": "Will SAP AI solutions replace ABAP developers?", "a": "No; what changes is how the work is distributed. Drafting recurring patterns becomes automated, and developers'' time shifts to design, review and getting business rules right. Responsibility for the code that goes to production stays with the team."}, {"q": "Isn''t a general-purpose AI assistant enough for ABAP development?", "a": "It''s often enough for syntax, not for your environment. Because it doesn''t know your Z objects, naming rules and in-house development standards, adapting the generated code to your system still falls to your team."}, {"q": "Can AI-generated ABAP code go straight to production?", "a": "It shouldn''t. The generated development should go through the same review, testing and approval steps as your existing change process. The assistant''s role is to speed that process up, not to skip it."}, {"q": "Is AI still useful if our Z objects aren''t documented?", "a": "Undocumented doesn''t mean unreadable. An approach that takes the structure of the objects in the system as input can make visible what an object does today and where a planned change will have an impact."}], "cover": "/images/ash-blog-sap-ai.en.svg", "seoTitle": "SAP AI and ABAP Development", "coverAlt": ""}'::jsonb) on conflict (locale,slug) do nothing;

commit;

select 'Kurulum tamamlandi' as sonuc, (select count(*) from public.ash_blog_posts) as yazi_sayisi, (select count(*) from public.ash_admins) as yonetici_sayisi;
